data class Task(val id: Long, val title: String, val done: Boolean = false)

interface TaskRepository {
    fun findById(id: Long): Task?
    fun getAll(): List<Task>
    fun save(task: Task)
    fun delete(id: Long)
}

class InMemoryTaskRepository : TaskRepository {
    private val tasks = linkedMapOf<Long, Task>()

    override fun findById(id: Long): Task? = tasks[id]
    override fun getAll(): List<Task> = tasks.values.toList()

    override fun save(task: Task) {
        require(task.title.isNotBlank()) { "Task title cannot be blank" }
