import operator

OPERATIONS = {
    "+": operator.add,
    "-": operator.sub,
    "*": operator.mul,
    "/": operator.truediv,
}

def calculate(left: float, operation: str, right: float) -> float:
    if operation not in OPERATIONS:
        raise ValueError("unsupported operation")
    if operation == "/" and right == 0:
        raise ValueError("division by zero")
    return OPERATIONS[operation](left, right)

def main() -> None:
    print("Calculator. Enter q to quit.")
    while True:
        first = input("First number: ").strip()
        if first.lower() in {"q", "quit", "выход"}:
            break
        operation = input("Operation (+ - * /): ").strip()
        second = input("Second number: ").strip()
        try:
            result = calculate(float(first), operation, float(second))
        except ValueError as error:
            print(f"Error: {error}")
        else:
            print(f"Result: {result:g}")

if __name__ == "__main__":
    main()
