Предмет описывается Resource: в редакторе создаёшь файлы .tres (ПКМ в FileSystem > New Resource > ItemData) и заполняешь поля без кода. Инвентарь хранит слоты как null или словарь с предметом и количеством. add_item сначала дополняет существующие стеки, затем занимает пустые слоты и возвращает остаток, поэтому вызывающий код знает, что инвентарь полон. remove_item сначала проверяет, хватает ли предметов, чтобы не удалить часть и не вернуть false. Сигнал changed заставляет интерфейс перерисоваться.

Полный пример кода:
```gdscript
# ===== ItemData.gd =====
class_name ItemData
extends Resource

@export var id: StringName
@export var display_name: String = ''
@export var icon: Texture2D
@export var max_stack: int = 99
@export_multiline var description: String = ''

# ===== Inventory.gd =====
class_name Inventory
extends Node

signal changed

@export var slot_count: int = 20

var slots: Array = []

func _ready() -> void:
	slots.resize(slot_count)

func add_item(item: ItemData, amount: int = 1) -> int:
	# Возвращает, сколько не поместилось.
	for slot in slots:
		if amount == 0:
			break
		if slot != null and slot['item'] == item and slot['count'] < item.max_stack:
			var moved: int = mini(item.max_stack - slot['count'], amount)
			slot['count'] += moved
			amount -= moved
	for i in slots.size():
		if amount == 0:
			break
		if slots[i] == null:
			var moved: int = mini(item.max_stack, amount)
			slots[i] = {'item': item, 'count': moved}
			amount -= moved
	changed.emit()
	return amount

func count_item(item: ItemData) -> int:
	var total: int = 0
	for slot in slots:
		if slot != null and slot['item'] == item:
			total += slot['count']
	return total

func remove_item(item: ItemData, amount: int = 1) -> bool:
	if count_item(item) < amount:
		return false
	for i in slots.size():
		if amount == 0:
			break
		var slot = slots[i]
		if slot != null and slot['item'] == item:
			var taken: int = mini(slot['count'], amount)
			slot['count'] -= taken
			amount -= taken
			if slot['count'] == 0:
				slots[i] = null
	changed.emit()
	return true
```

