Объяснение:
Vector2 и объекты не сериализуются в JSON напрямую, поэтому позиция хранится массивом из двух чисел. JSON возвращает все числа как float, поэтому значения приводятся явно. Версия в файле позволит позже изменить формат и не сломать старые сохранения. Загрузка проверяет, что файл существует, читается и имеет ожидаемую структуру, иначе возвращает пустой словарь, и игра не падает. Каждый игровой объект сам отвечает за свои данные через get_save_data и apply_save_data, а SaveSystem только пишет и читает файл. В записи 3 текущее здоровье задаётся напрямую, поэтому сигнал вызывается вручную, чтобы HUD обновился.

Полный пример кода:
```gdscript
# ===== SaveSystem.gd (Project Settings > Globals > Autoload) =====
extends Node

const SAVE_PATH: String = 'user://savegame.json'
const SAVE_VERSION: int = 1

func save_game(data: Dictionary) -> bool:
	var payload: Dictionary = {'version': SAVE_VERSION, 'data': data}
	var file: FileAccess = FileAccess.open(SAVE_PATH, FileAccess.WRITE)
	if file == null:
		push_error('Не удалось открыть файл сохранения: ' + str(FileAccess.get_open_error()))
		return false
	file.store_string(JSON.stringify(payload, '\t'))
	return true

func has_save() -> bool:
	return FileAccess.file_exists(SAVE_PATH)

func load_game() -> Dictionary:
	if not has_save():
		return {}
	var file: FileAccess = FileAccess.open(SAVE_PATH, FileAccess.READ)
	if file == null:
		return {}
	var parsed: Variant = JSON.parse_string(file.get_as_text())
	if not (parsed is Dictionary):
		push_warning('Файл сохранения повреждён')
		return {}
	if int(parsed.get('version', 0)) != SAVE_VERSION:
		push_warning('Неизвестная версия сохранения')
		return {}
	return parsed.get('data', {})

