Экспоненциальный коэффициент сглаживания сохраняет близкое поведение при разном FPS.

```gdscript
extends Camera2D

@export var target: Node2D
@export_range(0.1, 20.0) var follow_speed := 8.0

func _process(delta: float) -> void:
    if target == null:
        return
    var weight := 1.0 - exp(-follow_speed * delta)
    global_position = global_position.lerp(target.global_position, weight)
