Проверяем лимит до создания экземпляра. Координаты выбираются равномерно внутри прямоугольника.

```gdscript
extends Node2D

@export var scene: PackedScene
@export var spawn_area := Vector2(400, 250)
@export var max_alive := 5
var _alive: Array[Node] = []

func spawn_one() -> Node:
    _alive = _alive.filter(func(item): return is_instance_valid(item))
    if scene == null or _alive.size() >= max_alive:
        return null
    var instance := scene.instantiate()
    if not instance is Node2D:
        instance.queue_free()
        return null
    var half := spawn_area * 0.5
    instance.position = Vector2(randf_range(-half.x, half.x), randf_range(-half.y, half.y))
    add_child(instance)
    _alive.append(instance)
    return instance
```

